<?php
namespace App\Services;use App\Models\{RhAvenantContrat,RhContrat};use Illuminate\Support\Facades\DB;
class RhContractNumberService{public function contrat(int $entrepriseId,int $annee):string{return DB::transaction(function()use($entrepriseId,$annee){$prefix="CTR-$annee-";$nums=RhContrat::withTrashed()->where('entreprise_id',$entrepriseId)->where('numero','like',$prefix.'%')->lockForUpdate()->pluck('numero');$next=1;foreach($nums as $n)$next=max($next,(int)substr($n,strlen($prefix))+1);return $prefix.str_pad((string)$next,4,'0',STR_PAD_LEFT);});}public function avenant(int $entrepriseId,int $annee):string{$prefix="AVN-$annee-";$nums=RhAvenantContrat::withTrashed()->where('entreprise_id',$entrepriseId)->where('numero','like',$prefix.'%')->pluck('numero');$next=1;foreach($nums as $n)$next=max($next,(int)substr($n,strlen($prefix))+1);return $prefix.str_pad((string)$next,4,'0',STR_PAD_LEFT);}}
